            "kind": "user_turn",
            "prompt": clip(j.get("text"), TEXT_CLIP),
            "extra": {"session_id": SESSION_ID, "source": SOURCE,
                      "files": [f.get("uri") for f in (j.get("files") or []) if isinstance(f, dict)]},
        })
    elif type_ == "assistant":
        info = j
        created = info.get("time", {}).get("created", ts)
        text = "".join(
            c.get("text", "") for c in info.get("content", [])
            if isinstance(c, dict) and c.get("type") == "text"
        )
        model = info.get("model") or {}
        counts["llm_call"] += 1
        record({
            "created_ms": created,
            "kind": "llm_call",
            "model": f"{model.get('providerID', '?')}/{model.get('id', '?')}"
                     + (f"#{model['variant']}" if model.get("variant") else ""),
            "response": clip(text, TEXT_CLIP),
            "extra": {"session_id": SESSION_ID, "source": SOURCE,
                      "agent": info.get("agent"), "tokens": info.get("tokens"),
                      "cost": info.get("cost"), "time": info.get("time")},
        })
        for c in info.get("content", []):
            if not (isinstance(c, dict) and c.get("type") == "tool"):
                continue
            state = c.get("state") or {}
            meta = state.get("metadata") or {}
            counts["tool_call"] += 1
            record({
                "created_ms": (c.get("time") or {}).get("created", created),
                "kind": "tool_call",
                "tool_name": str(c.get("name", "unknown")),
                "error": None if state.get("status") == "completed" else clip(state.get("status"), 4000),
                "extra": {"session_id": SESSION_ID, "source": SOURCE,
                          "call_id": c.get("id"),
                          "status": state.get("status"),
                          "input": clip(state.get("input"), TOOL_CLIP),
                          "result": clip(
                              "".join(p.get("text", "") for p in state.get("content", [])
                                      if isinstance(p, dict) and p.get("type") == "text"),
                              TOOL_CLIP),
                          "exit": meta.get("exit")},
            })

print("recorded:", counts)
"}
